/**
 * A custom HTML element used to wrap secret blocks in HTML content in order to provide additional interactivity.
 */
class HTMLSecretBlockElement extends HTMLElement {
  /**
   * The HTML tag named used by this element.
   * @type {string}
   */
  static tagName = "secret-block";

  /* -------------------------------------------- */

  /**
   * A reference to the reveal button, if it exists.
   * @type {HTMLButtonElement}
   */
  #button;

  /* -------------------------------------------- */

  /**
   * The wrapped secret block.
   * @type {HTMLElement}
   */
  get secret() {
    return this.querySelector(":scope > .secret");
  }

  /* -------------------------------------------- */

  /**
   * The revealed state of the secret block.
   * @type {boolean}
   */
  get revealed() {
    return this.secret.classList.contains("revealed");
  }

  /* -------------------------------------------- */

  /** @override */
  connectedCallback() {
    if ( !this.#button ) this.#addRevealButton();
  }

  /* -------------------------------------------- */

  /**
   * Toggle the secret revealed or hidden state in content that this secret block represents.
   * @param {string} content  The raw string content for this secret.
   * @returns {string}        The modified raw content.
   */
  toggleRevealed(content) {
    const id = this.secret.id;
    const regex = new RegExp(`<section[^i]+id="${id}"[^>]*>`);
    return content.replace(regex, () => `<section class="secret${this.revealed ? "" : " revealed"}" id="${id}">`);
  }

  /* -------------------------------------------- */

  /**
   * Add a button that can be used to reveal or hide the secret block.
   */
  #addRevealButton() {
    const button = this.#button = document.createElement("button");
    Object.assign(button, { type: "button", className: "reveal" });
    button.append(game.i18n.localize(`EDITOR.${this.revealed ? "Hide" : "Reveal"}`));
    button.addEventListener("click", this.#onReveal.bind(this));
    this.secret.insertAdjacentElement("afterbegin", button);
  }

  /* -------------------------------------------- */

  /**
   * Handle toggling the hidden/revealed state of the secret block.
   */
  #onReveal() {
    this.dispatchEvent(new Event("change", { bubbles: true, cancelable: true }));
  }
}

/**
 * @import Document from "@common/abstract/document.mjs";
 * @import {DatabaseCreateOperation, DatabaseUpdateOperation} from "@common/abstract/_types.mjs";
 * @import {ApplicationClickAction, ApplicationConfiguration, ApplicationRenderOptions} from "../_types.mjs";
 * @import FormDataExtended from "../ux/form-data-extended.mjs";
 */

/**
 * @typedef DocumentSheetConfiguration
 * @property {Document} document          The Document instance associated with this sheet
 * @property {number} viewPermission      A permission level in CONST.DOCUMENT_OWNERSHIP_LEVELS
 * @property {number} editPermission      A permission level in CONST.DOCUMENT_OWNERSHIP_LEVELS
 * @property {boolean} canCreate          Can this sheet class be used to create a new Document?
 * @property {boolean} sheetConfig        Allow sheet configuration as a header button
 */

/**
 * @typedef DocumentSheetRenderOptions
 * @property {string} renderContext       A string with the format "{operation}{documentName}" providing context
 * @property {object} renderData          Data describing the document modification that occurred
 */

/**
 * The Application class is responsible for rendering an HTMLElement into the Foundry Virtual Tabletop user interface.
 * @extends {ApplicationV2<
 *  ApplicationConfiguration & DocumentSheetConfiguration,
 *  ApplicationRenderOptions & DocumentSheetRenderOptions
 * >}
 */
class DocumentSheetV2 extends ApplicationV2 {
  /** @inheritDoc */
  constructor(options, ...args) {
    options = new.target._migrateConstructorParams(options, args);
    super(options);
    this.#document = options.document;
  }

  /** @inheritDoc */
  static DEFAULT_OPTIONS = {
    id: "{id}",
    classes: ["sheet"],
    tag: "form",  // Document sheets are forms by default
    document: null,
    viewPermission: DOCUMENT_OWNERSHIP_LEVELS.LIMITED,
    editPermission: DOCUMENT_OWNERSHIP_LEVELS.OWNER,
    canCreate: false,
    sheetConfig: true,
    actions: {
      configureSheet: DocumentSheetV2.#onConfigureSheet,
      copyUuid: {handler: DocumentSheetV2.#onCopyUuid, buttons: [0, 2]},
      editImage: DocumentSheetV2.#onEditImage,
      importDocument: DocumentSheetV2.#onImportDocument
    },
    form: {
      handler: this.#onSubmitDocumentForm,
      submitOnChange: false,
      closeOnSubmit: false
    },
    window: {
      controls: [{
        icon: "fa-solid fa-gear",
        label: "SHEETS.ConfigureSheet",
        action: "configureSheet",
        visible: DocumentSheetV2.#canConfigureSheet
      }]
    }
  };

  /* -------------------------------------------- */

  /**
   * The Document instance associated with the application
   * @type {ClientDocument}
   */
  get document() {
    return this.#document;
  }

  #document;

  /* -------------------------------------------- */

  /** @override */
  get title() {
    const {constructor: cls, id, name, type} = this.document;
    const prefix = cls.hasTypeData && type !== "base" ? CONFIG[cls.documentName].typeLabels[type] : cls.metadata.label;
    return `${game.i18n.localize(prefix)}: ${name || id}`;
  }

  /* -------------------------------------------- */

  /**
   * Is this Document sheet visible to the current User?
   * This is governed by the viewPermission threshold configured for the class.
   * @type {boolean}
   */
  get isVisible() {
    return this.document.testUserPermission(game.user, this.options.viewPermission);
  }

  /* -------------------------------------------- */

  /**
   * Is this Document sheet editable by the current User?
   * This is governed by the editPermission threshold configured for the class.
   * @type {boolean}
   */
  get isEditable() {
    if ( this.document.pack ) {
      const pack = game.packs.get(this.document.pack);
      if ( pack.locked ) return false;
    }
    return this.document.testUserPermission(game.user, this.options.editPermission);
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  _initializeApplicationOptions(options) {
    options = super._initializeApplicationOptions(options);
    const suffix = options.document.uuid ?? foundry.utils.randomID();
    options.uniqueId = `${this.constructor.name}-${suffix.replaceAll(".", "-")}`;
    const theme = foundry.applications.apps.DocumentSheetConfig.getSheetThemeForDocument(options.document);
    if ( theme && !options.classes.includes("themed") ) options.classes.push("themed", `theme-${theme}`);
    return options;
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  *_headerControlButtons() {
    for ( const control of super._headerControlButtons() ) {
      if ( ("ownership" in control) && !this.document.testUserPermission(game.user, control.ownership) ) continue;
      yield control;
    }
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  _configureRenderOptions(options) {
    super._configureRenderOptions(options);

    // If the Document's name was changed, update the window title.
    if ( this.hasFrame && options.renderContext && options.renderData?.name ) {
      options.window = Object.assign(options.window ?? {}, {title: this.title});
    }
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  async _prepareContext(options) {
    const context = await super._prepareContext(options);
    const document = this.document;
    return Object.assign(context, {
      document,
      source: document._source,
      fields: document.schema.fields,
      editable: this.isEditable,
      user: game.user,
      rootId: document.collection?.has(document.id) ? this.id : foundry.utils.randomID()
    });
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  async _renderFrame(options) {
    const frame = await super._renderFrame(options);
    if ( !this.hasFrame ) return frame;

    // Add form options
    if ( this.options.tag === "form" ) frame.autocomplete = "off";

    // Add document ID copy
    if ( this.document.id ) {
      const copyLabel = game.i18n.localize("SHEETS.CopyUuid");
      const copyId = `
        <button type="button" class="header-control fa-solid fa-passport icon" data-action="copyUuid"
                data-tooltip="${copyLabel}" aria-label="${copyLabel}"></button>
      `;
      this.window.close.insertAdjacentHTML("beforebegin", copyId);
    }

    // Add compendium import
    const { documentName, isEmbedded, inCompendium } = this.document;
    if ( (documentName !== "Folder") && !isEmbedded && inCompendium ) {
      this.window.close.insertAdjacentHTML("beforebegin", `
        <button type="button" class="header-control fa-solid fa-download icon" data-action="importDocument"
                data-tooltip="Import" aria-label="${game.i18n.localize("Import")}"></button>
      `);
    }

    return frame;
  }

  /* -------------------------------------------- */

  /**
   * Disable or reenable all form fields in this application.
   * @param {boolean} disabled Should the fields be disabled?
   * @protected
   */
  _toggleDisabled(disabled) {
    const form = this.form;
    if ( !this.form ) return;
    const framed = this.options.window.frame;
    for ( const element of form.elements ) {
      if ( !framed || element.closest(".window-content") ) element.disabled = disabled;
    }
    const contentEl = framed ? form.querySelector(".window-content") : form;
    for ( const input of contentEl.querySelectorAll("input[type=image]") ) {
      input.disabled = disabled; // By specification, these are not included in a HTMLFormControlsCollection
    }
    for ( const img of contentEl.querySelectorAll("img[data-edit]") ) {
      img.classList.toggle("disabled", disabled);
    }
  }

  /* -------------------------------------------- */
  /*  Application Life-Cycle Events               */
  /* -------------------------------------------- */

  /** @override */
  _canRender(_options) {
    if ( !this.isVisible ) throw new Error(game.i18n.format("SHEETS.DocumentSheetPrivate", {
      type: game.i18n.localize(this.document.constructor.metadata.label)
    }));
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  async _onFirstRender(context, options) {
    await super._onFirstRender(context, options);
    this.document.apps[this.id] = this;
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  async _onRender(context, options) {
    await super._onRender(context, options);
    if ( !this.isEditable ) this._toggleDisabled(true);
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  _onClose(options) {
    super._onClose(options);
    delete this.document.apps[this.id];
  }

  /* -------------------------------------------- */
  /*  Event Listeners and Handlers                */
  /* -------------------------------------------- */

  /**
   * Whether it's possible to configure this Document's sheet.
   * @this {DocumentSheetV2}
   * @returns {boolean}
   */
  static #canConfigureSheet() {
    if ( !this.options.sheetConfig || !this.isEditable ) return false;
    const document = this.#document;
    return !!document.collection?.has(document.id) && !document.flags.core?.sheetLock;
  }

  /* -------------------------------------------- */

  /**
   * Handle click events to configure the sheet used for this document.
   * @param {PointerEvent} event
   * @this {DocumentSheetV2}
   */
  static #onConfigureSheet(event) {
    event.stopPropagation(); // Don't trigger other events
    if ( event.detail > 1 ) return; // Ignore repeated clicks

    const docSheetConfigWidth = foundry.applications.apps.DocumentSheetConfig.DEFAULT_OPTIONS.position.width;
    new foundry.applications.apps.DocumentSheetConfig({
      document: this.document,
      position: {
        top: this.position.top + 40,
        left: this.position.left + ((this.position.width - docSheetConfigWidth) / 2)
      }
    }).render({ force: true });
  }

  /* -------------------------------------------- */

  /**
   * Handle click events to copy the UUID of this document to clipboard.
   * @param {PointerEvent} event
   * @this {DocumentSheetV2}
   */
  static #onCopyUuid(event) {
    event.preventDefault(); // Don't open context menu
    event.stopPropagation(); // Don't trigger other events
    if ( event.detail > 1 ) return; // Ignore repeated clicks
    const id = event.button === 2 ? this.document.id : this.document.uuid;
    const type = event.button === 2 ? "id" : "uuid";
    const label = game.i18n.localize(this.document.constructor.metadata.label);
    game.clipboard.copyPlainText(id);
    ui.notifications.info("DOCUMENT.IdCopiedClipboard", {format: {label, type, id}});
  }

  /**
   * Edit a Document image.
   * @this {DocumentSheetV2}
   * @type {ApplicationClickAction}
   */
  static async #onEditImage(_event, target) {
    if ( target.nodeName !== "IMG" ) {
      throw new Error("The editImage action is available only for IMG elements.");
    }
    const attr = target.dataset.edit;
    const current = foundry.utils.getProperty(this.document._source, attr);
    const defaultArtwork = this.document.constructor.getDefaultArtwork?.(this.document._source) ?? {};
    const defaultImage = foundry.utils.getProperty(defaultArtwork, attr);
    const fp = new FilePicker.implementation({
      current,
      type: "image",
      redirectToRoot: defaultImage ? [defaultImage] : [],
      callback: path => {
        target.src = path;
        if ( this.options.form.submitOnChange ) {
          const submit = new Event("submit", {cancelable: true});
          this.form.dispatchEvent(submit);
        }
      },
      position: {
        top: this.position.top + 40,
        left: this.position.left + 10
      }
    });
    await fp.browse();
  }

  /* -------------------------------------------- */

  /**
   * Handle importing a document from a compendium pack.
   * @this {DocumentSheetV2}
   */
  static async #onImportDocument() {
    await this.close();
    const { documentName, collection, id } = this.document;
    return game.collections.get(documentName).importFromCompendium(collection, id);
  }

  /* -------------------------------------------- */
  /*  Form Submission                             */
  /* -------------------------------------------- */

  /** @inheritDoc */
  _onChangeForm(formConfig, event) {
    if ( event.target instanceof HTMLSecretBlockElement ) return this._onRevealSecret(event);
    super._onChangeForm(formConfig, event);
  }

  /* -------------------------------------------- */

  /**
   * Handle toggling the revealed state of a secret embedded in some content.
   * @param {Event} event  The triggering event.
   * @protected
   */
  _onRevealSecret(event) {
    const editor = event.target.closest("prose-mirror");
    if ( !editor?.name ) return;
    const content = foundry.utils.getProperty(this.document, editor.name);
    const modified = event.target.toggleRevealed(content);
    this.document.update({ [editor.name]: modified });
  }

  /* -------------------------------------------- */

  /**
   * Process form submission for the sheet.
   * @this {DocumentSheetV2}                      The handler is called with the application as its bound scope
   * @param {SubmitEvent} event                   The originating form submission event
   * @param {HTMLFormElement} form                The form element that was submitted
   * @param {FormDataExtended} formData           Processed data for the submitted form
   * @param {object} [options]                    Additional options provided by a manual submit call. All options
   *                                              except `options.updateData` are forwarded along to _processSubmitData.
   * @param {object} [options.updateData]         Additional data passed in if this form is submitted manually which
   *                                              should be merged with prepared formData.
   * @returns {Promise<void>}
   */
  static async #onSubmitDocumentForm(event, form, formData, options={}) {
    if ( !this.isEditable ) return;
    const {updateData, ...updateOptions} = options;
    const submitData = this._prepareSubmitData(event, form, formData, updateData);
    await this._processSubmitData(event, form, submitData, updateOptions);
  }

  /* -------------------------------------------- */

  /**
   * Prepare data used to update the Document upon form submission.
   * This data is cleaned and validated before being returned for further processing.
   * @param {SubmitEvent} event                   The originating form submission event
   * @param {HTMLFormElement} form                The form element that was submitted
   * @param {FormDataExtended} formData           Processed data for the submitted form
   * @param {object} [updateData]                 Additional data passed in if this form is submitted manually which
   *                                              should be merged with prepared formData.
   * @returns {object}                            Prepared submission data as an object
   * @throws {Error}                              Subclasses may throw validation errors here to prevent form submission
   * @protected
   */
  _prepareSubmitData(event, form, formData, updateData) {
    const submitData = this._processFormData(event, form, formData);
    if ( updateData ) {
      foundry.utils.mergeObject(submitData, updateData, {performDeletions: true});
      foundry.utils.mergeObject(submitData, updateData, {performDeletions: false});
    }
    this.document.validate({changes: submitData, clean: true, fallback: false});
    return submitData;
  }

  /* -------------------------------------------- */

  /**
   * Customize how form data is extracted into an expanded object.
   * @param {SubmitEvent|null} event              The originating form submission event
   * @param {HTMLFormElement} form                The form element that was submitted
   * @param {FormDataExtended} formData           Processed data for the submitted form
   * @returns {object}                            An expanded object of processed form data
   * @throws {Error}                              Subclasses may throw validation errors here to prevent form submission
   * @protected
   */
  _processFormData(event, form, formData) {
    return foundry.utils.expandObject(formData.object);
  }

  /* -------------------------------------------- */

  /**
   * Submit a document update or creation request based on the processed form data.
   * @param {SubmitEvent} event                   The originating form submission event
   * @param {HTMLFormElement} form                The form element that was submitted
   * @param {object} submitData                   Processed and validated form data to be used for a document update
   * @param {Partial<DatabaseCreateOperation|DatabaseUpdateOperation>} [options] Additional options altering the request
   * @returns {Promise<void>}
   * @protected
   */
  async _processSubmitData(event, form, submitData, options={}) {
    const document = this.#document;
    if ( document.collection?.has(document.id) ) {
      await document.update(submitData, options);
    }
    else if ( this.options.canCreate ) {
      const {parent, pack} = document;
      const operation = Object.assign(options, {parent, pack, keepId: true});
      const created = await document.constructor.create(submitData, operation);
      if ( created ) {
        if ( !document.id && document.rendered ) document.object.destroy({children: true});
        this.#document = created;
      }
      else throw new Error("Failed to create document.");
    }
    else {
      throw new Error(`Document creation from ${this.constructor.name} is not supported.`);
    }
  }

  /* -------------------------------------------- */
  /*  Deprecation and Compatibility               */
  /* -------------------------------------------- */

  /**
   * Provide a deprecation path for converted V1 document sheets.
   * @param {unknown} first The first parameter received by this class's constructor
   * @param {unknown[]} rest Any additional parameters received
   * @returns {Partial<ApplicationConfiguration & DocumentSheetConfiguration>}
   * @internal
   */
  static _migrateConstructorParams(first, rest) {
    if ( (first instanceof Object) && (first.document instanceof foundry.abstract.Document) ) {
      return first;
    }

    // Probably using V1 constructor args, but make sure the first is in fact a Document.
    if ( !(first instanceof foundry.abstract.Document) ) {
      throw new Error("A DocumentSheetV2 application must be provided a Document instance.");
    }

    // Warn, create a new partial configuration object, and recover at least some of the other options.
    const message = [
      `DocumentSheet V1 arguments passed to a ${this.name} constructor`,
      "the first argument must be an options object with a document property."
    ].join(": ");
    foundry.utils.logCompatibilityWarning(message, {since: 13, until: 15});
    const options = {document: first};
    const legacyOptions = rest[1] instanceof Object ? rest[1] : {};
    if ( typeof legacyOptions.title === "string" ) options.window = {title: legacyOptions.title};
    const positionKeys = ["top", "left", "width", "height", "scale", "zIndex"];
    options.position = positionKeys.reduce((position, key) => {
      if ( legacyOptions[key] !== undefined ) position[key] = legacyOptions[key];
      return position;
    }, {});
    return options;
  }
}

/**
 * @import {ApplicationConfiguration, ApplicationRenderContext, ApplicationRenderOptions} from "../_types.mjs";
 * @import {DocumentSheetConfiguration, DocumentSheetRenderOptions} from "../api/document-sheet.mjs";
 * @import Application from "@client/appv1/api/application-v1.mjs";
 * @import ApplicationV2 from "../api/application.mjs";
 */

/**
 * @typedef DefaultSheetDescriptor
 * @property {string} sheet  The identifier of the default sheet.
 * @property {string} theme  The default theme.
 */

/**
 * @typedef SheetRegistrationDescriptor
 * @property {typeof ClientDocument} documentClass  The Document class to register a new sheet option for.
 * @property {string} id                            The identifier of the sheet being registered.
 * @property {typeof Application|typeof ApplicationV2} sheetClass An Application class used to render the sheet.
 * @property {string|(()=>string)} [label]          A human-readable label for the sheet name, or a function that
 *                                                  returns one. Will be localized.
 * @property {string[]} [types]                     An array of Document sub-types to register the sheet for.
 * @property {Record<string, string>|null} [themes] An object of theme keys to labels that the sheet supports. If this
 *                                                  option is not supplied, the sheet is assumed to support both light
 *                                                  and dark themes. If null is supplied, it indicates that the sheet
 *                                                  does not support theming.
 * @property {boolean} [makeDefault=false]          Whether to make this sheet the default for the provided sub-types.
 * @property {boolean} [canBeDefault=true]          Whether this sheet is available to be selected as a default sheet
 *                                                  for all Documents of that type.
 * @property {boolean} [canConfigure=true]          Whether this sheet appears in the sheet configuration UI for users.
 */

/**
 * @typedef {Omit<SheetRegistrationDescriptor, "documentClass"|"id"|"sheetClass">} SheetRegistrationOptions
 */

/**
 * @typedef DocumentSheetConfigRenderContext
 * @property {DocumentSheetConfigFieldDescriptor} sheet  Context for the sheet field.
 * @property {DocumentSheetConfigFieldDescriptor} theme  Context for the theme field.
 */

/**
 * @typedef DocumentSheetConfigFieldDescriptor
 * @property {DataField} field     The field instance.
 * @property {string} name         The field's form name.
 * @property {string} value        The field's value.
 * @property {boolean} [disabled]  Whether the field should be disabled in the form.
 */

/**
 * An Application for configuring Document sheet settings.
 * @extends {ApplicationV2<
 *  ApplicationConfiguration & DocumentSheetConfiguration,
 *  ApplicationRenderOptions & DocumentSheetRenderOptions
 * >}
 * @mixes HandlebarsApplication
 */
class DocumentSheetConfig extends HandlebarsApplicationMixin(DocumentSheetV2) {
  /** @override */
  static DEFAULT_OPTIONS = {
    id: "sheet-config-{id}",
    classes: ["sheet-config"],
    sheetConfig: false,
    window: {
      contentClasses: ["standard-form"],
      icon: "fa-solid fa-gear"
    },
    position: {width: 500},
    form: {
      handler: DocumentSheetConfig.#onSubmitForm,
      closeOnSubmit: true
    }
  };

  /** @override */
  static PARTS = {
    form: {
      classes: ["standard-form"],
      template: "templates/sheets/document-sheet-config.hbs"
    },
    footer: {
      template: "templates/generic/form-footer.hbs"
    }
  };

  /* -------------------------------------------- */
  /*  Properties                                  */
  /* -------------------------------------------- */

  /**
   * The cached render context for the sheet defaults.
   * @type {DocumentSheetConfigRenderContext}
   */
  #defaults;

  /**
   * The cached render context for the Document.
   * @type {DocumentSheetConfigRenderContext}
   */
  #document;

  /** @override */
  get title() {
    const { constructor: cls, documentName, type } = this.document;
    const prefix = cls.hasTypeData && (type !== "base")
      ? CONFIG[documentName].typeLabels[type]
      : cls.metadata.label;
    return game.i18n.format("SHEETS.ConfigureTitle", { prefix: game.i18n.localize(prefix) });
  }

  /* -------------------------------------------- */
  /*  Rendering                                   */
  /* -------------------------------------------- */

  /** @override */
  async _preparePartContext(partId, context, options) {
    context.partId = partId;
    switch ( partId ) {
      case "footer": await this._prepareFooterContext(context, options); break;
      case "form": await this._prepareFormContext(context, options); break;
    }
    return context;
  }

  /* -------------------------------------------- */

  /**
   * Prepare render context for the footer part.
   * @param {ApplicationRenderContext} context
   * @param {ApplicationRenderOptions} options
   * @returns {Promise<void>}
   * @protected
   */
  async _prepareFooterContext(context, options) {
    context.buttons = [{
      type: "submit",
      icon: "fa-solid fa-floppy-disk",
      label: "SHEETS.Save"
    }];
  }

  /* -------------------------------------------- */

  /**
   * Prepare render context for the form part.
   * @param {ApplicationRenderContext} context
   * @param {ApplicationRenderOptions} options
   * @returns {Promise<void>}
   * @protected
   */
  async _prepareFormContext(context, options) {
    const document = this.document;
    const { documentName, type=CONST.BASE_DOCUMENT_TYPE } = document;
    const {
      sheetClasses, defaultClasses, defaultClass
    } = DocumentSheetConfig.getSheetClassesForSubType(documentName, type);
    const sheetClass = document.flags.core?.sheetClass ?? "";
    const config = CONFIG[documentName].sheetClasses[type] ?? {};
    const themes = game.settings.get("core", "sheetThemes");
    const currentClass = sheetClass || defaultClass;

    context.document = this.#document = {
      sheet: {
        field: new foundry.data.fields.StringField({
          label: "SHEETS.ThisSheet",
          hint: "SHEETS.DocumentSheetHint",
          choices: sheetClasses
        }),
        name: "sheetClass",
        value: sheetClass
      },
      theme: {
        field: new foundry.data.fields.StringField({
          label: "SHEETS.Theme",
          hint: "SHEETS.ThemeHint",
          choices: config[currentClass]?.themes ?? {}
        }),
        name: "theme",
        value: themes.documents?.[document.uuid] || "",
        disabled: isSubclass(config[currentClass]?.cls, foundry.appv1.api.Application)
      }
    };

    context.defaults = this.#defaults = {
      sheet: {
        field: new foundry.data.fields.StringField({
          label: "SHEETS.DefaultSheet",
          hint: "SHEETS.TypeSheetHint",
          choices: defaultClasses
        }),
        name: "defaultClass",
        disabled: !game.user.isGM,
        value: defaultClass
      },
      theme: {
        field: new foundry.data.fields.StringField({
          label: "SHEETS.Theme",
          hint: "SHEETS.ThemeHint",
          choices: config[defaultClass]?.themes ?? {}
        }),
        name: "defaultTheme",
        value: foundry.utils.getProperty(themes, `defaults.${documentName}.${type}`) || "",
        disabled: isSubclass(config[defaultClass]?.cls, foundry.appv1.api.Application)
      }
    };
  }

  /* -------------------------------------------- */
  /*  Event Listeners & Handlers                  */
  /* -------------------------------------------- */

  /** @inheritDoc */
  _onChangeForm(formConfig, event) {
    // Update theme options based on which sheet is selected.
    super._onChangeForm(formConfig, event);
    const { defaultTheme, theme } = new FormDataExtended(this.form).object;
    this.form.elements.defaultTheme.replaceChildren(...this.#defaults.theme.field.toInput({
      localize: true, blank: "Default"
    }).children);
    this.form.elements.defaultTheme.value = defaultTheme ?? "";
    this.form.elements.theme.replaceChildren(...this.#document.theme.field.toInput({
      localize: true, blank: "Default"
    }).children);
    this.form.elements.theme.value = theme ?? "";

    // Disable theme selection if the sheet class doesn't support it.
    if ( ["sheetClass", "defaultClass"].includes(event.target.name) ) {
      for ( const [sheetSelectName, themeSelectName] of [["sheetClass", "theme"], ["defaultTheme", "defaultTheme"]] ) {
        const sheetSelectEl = this.form.elements[sheetSelectName];
        const {documentName, type=CONST.BASE_DOCUMENT_TYPE} = this.document;
        const config = CONFIG[documentName].sheetClasses[type] ?? {};
        const sheetValue = sheetSelectEl.value || this.form.elements.defaultClass.value;
        const Cls = config[sheetValue]?.cls;
        this.form.elements[themeSelectName].disabled = isSubclass(Cls, foundry.appv1.api.Application);
      }
    }
  }

  /* -------------------------------------------- */

  /** @override */
  _onClose(_options) {}

  /* -------------------------------------------- */

  /** @override */
  _onFirstRender(_context, _options) {}

  /* -------------------------------------------- */

  /**
   * Process form submission for the sheet.
   * @this {DocumentSheetConfig}
   * @param {SubmitEvent} event          The form submission event.
   * @param {HTMLFormElement} form       The form element that was submitted.
   * @param {FormDataExtended} formData  Processed data for the submitted form.
   * @returns {Promise<void>}
   */
  static async #onSubmitForm(event, form, formData) {
    const { object } = formData;
    const { documentName, type=CONST.BASE_DOCUMENT_TYPE } = this.document;

    // Update themes.
    const themes = game.settings.get("core", "sheetThemes");
    const defaultTheme = foundry.utils.getProperty(themes, `defaults.${documentName}.${type}`);
    const documentTheme = themes.documents?.[this.document.uuid];
    const themeChanged = (object.defaultTheme !== defaultTheme) || (object.theme !== documentTheme);
    if ( themeChanged ) {
      foundry.utils.setProperty(themes, `defaults.${documentName}.${type}`, object.defaultTheme);
      themes.documents ??= {};
      themes.documents[this.document.uuid] = object.theme;
      await game.settings.set("core", "sheetThemes", themes);
    }

    // Update sheets.
    const { defaultClass } = this.constructor.getSheetClassesForSubType(documentName, type);
    const sheetClass = this.document.getFlag("core", "sheetClass") ?? "";
    const defaultSheetChanged = object.defaultClass !== defaultClass;
    const documentSheetChanged = object.sheetClass !== sheetClass;

    if ( themeChanged || (game.user.isGM && defaultSheetChanged) ) {
      if ( game.user.isGM && defaultSheetChanged ) {
        const setting = game.settings.get("core", "sheetClasses");
        foundry.utils.setProperty(setting, `${documentName}.${type}`, object.defaultClass);
        await game.settings.set("core", "sheetClasses", setting);
      }

      // Trigger a sheet change manually if it wouldn't be triggered by the normal ClientDocument#_onUpdate workflow.
      if ( !documentSheetChanged ) return this.document._onSheetChange({ sheetOpen: true });
    }

    // Update the document-specific override.
    if ( documentSheetChanged ) return this.document.setFlag("core", "sheetClass", object.sheetClass);
  }

  /* -------------------------------------------- */
  /*  Helpers                                     */
  /* -------------------------------------------- */

  /**
   * Marshal information on the available sheet classes for a given document type and sub-type, and format it for
   * display.
   * @param {string} documentName  The Document type.
   * @param {string} [subType]     The Document sub-type, if applicable.
   * @returns {{sheetClasses: Record<string, string>, defaultClasses: Record<string, string>, defaultClass: string}}
   */
  static getSheetClassesForSubType(documentName, subType) {
    subType ||= CONST.BASE_DOCUMENT_TYPE;
    let defaultClass;
    const config = CONFIG[documentName];
    const {defaultClasses, sheetClasses} = Object.values(config.sheetClasses[subType]).reduce((obj, cfg) => {
      if ( cfg.canConfigure ) obj.sheetClasses[cfg.id] = cfg.label;
      if ( cfg.default && !defaultClass ) defaultClass = cfg.id;
      if ( cfg.canConfigure && cfg.canBeDefault ) obj.defaultClasses[cfg.id] = cfg.label;
      return obj;
    }, {defaultClasses: {}, sheetClasses: {}});
    defaultClass ??= Object.keys(defaultClasses)[0];
    return {sheetClasses, defaultClasses, defaultClass};
  }

  /* -------------------------------------------- */

  /**
   * Retrieve the user's theme preference for the given Document.
   * @param {ClientDocument} document  The Document.
   * @returns {string}                 The theme identifier, or a blank string if the user has no preference.
   */
  static getSheetThemeForDocument(document) {
    const { documentName, uuid, type=CONST.BASE_DOCUMENT_TYPE } = document;
    const { defaultClass } = this.getSheetClassesForSubType(documentName, type);
    const sheetClass = document.getFlag("core", "sheetClass");
    const config = CONFIG[documentName].sheetClasses[type];
    const themes = config?.[sheetClass || defaultClass]?.themes ?? {};
    const setting = game.settings.get("core", "sheetThemes");
    const defaultTheme = foundry.utils.getProperty(setting, `defaults.${documentName}.${type}`);
    const documentTheme = setting.documents?.[uuid];
    if ( documentTheme && (documentTheme in themes) ) return documentTheme;
    if ( defaultTheme && (defaultTheme in themes) ) return defaultTheme;
    return "";
  }

  /* -------------------------------------------- */
  /*  Sheet Configuration API                     */
  /* -------------------------------------------- */

  /**
   * An array of pending sheet assignments which are submitted before other elements of the framework are ready.
   * @type {Array<SheetRegistrationDescriptor & { action: "register"|"unregister" }>}
   */
  static #pending = [];

  /* -------------------------------------------- */

  /**
   * Get the available Document sub-types for the given Document class.
   * @param {typeof ClientDocument} cls  The Document class.
   * @param {string[]} types             A sub-set of Document sub-types to return instead.
   */
  static #getDocumentTypes(cls, types=[]) {
    return types.length ? types : game.documentTypes[cls.documentName];
  }

  /* -------------------------------------------- */

  /**
   * Initialize the configured sheet preferences for Documents which support dynamic sheet assignment.
   * @returns {Promise<void>}
   */
  static async initializeSheets() {
    for ( const documentName of CONST.ALL_DOCUMENT_TYPES ) {
      const cls = foundry.utils.getDocumentClass(documentName);
      const types = DocumentSheetConfig.#getDocumentTypes(cls);
      CONFIG[documentName].sheetClasses = types.reduce((obj, type) => {
        obj[type] = {};
        return obj;
      }, {});
    }

    // Register any pending sheets.
    for ( const pending of DocumentSheetConfig.#pending ) {
      if ( pending.action === "register" ) DocumentSheetConfig.#registerSheet(pending);
      else if ( pending.action === "unregister" ) DocumentSheetConfig.#unregisterSheet(pending);
    }
    DocumentSheetConfig.#pending = [];

    // Update default sheet preferences.
    const defaults = game.settings.get("core", "sheetClasses");
    this.updateDefaultSheets(defaults);
  }

  /* -------------------------------------------- */

  /**
   * Register a sheet class as a candidate to be used to display Documents of a given type.
   * @param {typeof ClientDocument} documentClass                 The Document class to register a new sheet for.
   * @param {string} scope                                        A unique namespace scope for this sheet.
   * @param {typeof Application|typeof ApplicationV2} sheetClass  An Application class used to render the sheet.
   * @param {SheetRegistrationOptions} options                    Sheet registration configuration options.
   */
  static registerSheet(documentClass, scope, sheetClass, options={}) {
    const { label, types, themes, makeDefault=false, canBeDefault=true, canConfigure=true } = options;
    const id = `${scope}.${sheetClass.name}`;
    const config = { documentClass, id, label, sheetClass, types, themes, makeDefault, canBeDefault, canConfigure };
    if ( game.ready ) DocumentSheetConfig.#registerSheet(config);
    else {
      config.action = "register";
      this.#pending.push(config);
    }
  }

  /* -------------------------------------------- */

  /**
   * Perform the sheet registration.
   * @param {SheetRegistrationDescriptor} config  Sheet registration configuration.
   */
  static #registerSheet(config={}) {
    let { documentClass, id, label, sheetClass, types, themes, makeDefault, canBeDefault, canConfigure } = config;
    types = DocumentSheetConfig.#getDocumentTypes(documentClass, types);
    if ( themes === undefined ) {
      themes = {
        dark: "SETTINGS.UI.FIELDS.colorScheme.choices.dark",
        light: "SETTINGS.UI.FIELDS.colorScheme.choices.light"
      };
    }
    if ( label instanceof Function ) label = label();
    else if ( label ) label = game.i18n.localize(label);
    else label = id;
    const classes = CONFIG[documentClass.documentName]?.sheetClasses;
    const defaultSheets = game.settings.get("core", "sheetClasses");
    if ( foundry.utils.getType(classes) !== "Object" ) return;
    for ( const t of types ) {
      classes[t] ??= {};
      const existingDefault = defaultSheets[documentClass.documentName]?.[t];
      const isDefault = existingDefault ? existingDefault === id : makeDefault;
      if ( isDefault ) Object.values(classes[t]).forEach(s => s.default = false);
      classes[t][id] = {
        id, label, themes, canBeDefault, canConfigure,
        cls: sheetClass,
        default: isDefault
      };
    }
  }

  /* -------------------------------------------- */

  /**
   * Unregister a sheet class, removing it from the list of available Applications to use for a Document type.
   * @param {typeof ClientDocument} documentClass                 The Document class to register a new sheet option for.
   * @param {string} scope                                        A unique namespace scope for this sheet.
   * @param {typeof Application|typeof ApplicationV2} sheetClass  An Application class used to render the sheet.
   * @param {object} [options]
   * @param {string[]} [options.types]                            The sub-types this sheet should be removed for,
   *                                                              otherwise all sub-types are unregistered.
   */
  static unregisterSheet(documentClass, scope, sheetClass, { types }={}) {
    const id = `${scope}.${sheetClass.name}`;
    const config = { documentClass, id, types };
    if ( game.ready ) DocumentSheetConfig.#unregisterSheet(config);
    else {
      config.action = "unregister";
      this.#pending.push(config);
    }
  }

  /* -------------------------------------------- */

  /**
   * Perform the sheet de-registration.
   * @param {Partial<SheetRegistrationDescriptor>} config  Sheet de-registration configuration.
   */
  static #unregisterSheet(config={}) {
    let { documentClass, id, types } = config;
    types = DocumentSheetConfig.#getDocumentTypes(documentClass, types);
    const classes = CONFIG[documentClass.documentName]?.sheetClasses;
    if ( foundry.utils.getType(classes) !== "Object" ) return;
    for ( const t of types ) delete classes[t][id];
  }

  /* -------------------------------------------- */

  /**
   * Update the current default sheets using a new core World setting.
   * @param {Record<string, string>} setting  The stored default sheet settings.
   */
  static updateDefaultSheets(setting={}) {
    if ( foundry.utils.isEmpty(setting) ) return;
    for ( const documentName of CONST.ALL_DOCUMENT_TYPES ) {
      const cfg = CONFIG[documentName];
      const classes = cfg.sheetClasses;
      const collection = cfg.collection?.instance ?? [];
      const defaults = setting[documentName];
      if ( !defaults ) continue;

      // Update default preference for registered sheets.
      for ( const [type, sheetId] of Object.entries(defaults) ) {
        if ( !sheetId ) continue;
        const sheets = Object.values(classes[type] || {});
        const requested = sheets.find(s => s.id === sheetId);
        if ( requested ) sheets.forEach(s => s.default = s.id === sheetId);
      }

      // Close and de-register any existing sheets.
      for ( const document of collection ) {
        for ( const app of Object.values(document.apps) ) app.close();
        document._sheet = null;
      }
    }
  }
}

/**
 * @typedef DragDropConfiguration
 * @property {string|null} [dragSelector=null]  The CSS selector used to target draggable elements.
 * @property {string|null} [dropSelector=null]  The CSS selector used to target viable drop targets.
 * @property {Record<"dragstart"|"drop", (selector: string) => boolean>} [permissions]
 *                                         Permission tests for each action
 * @property {Record<
 *  "dragstart"|"dragover"|"drop"|"dragenter"|"dragleave"|"dragend",
 *  (event: DragEvent) => void
 * >} [callbacks]                         Callback functions for each action
 */

/**
 * A controller class for managing drag and drop workflows within an Application instance.
 * The controller manages the following actions: dragstart, dragover, drop.
 *
 * @example Activate drag-and-drop handling for a certain set of elements
 * ```js
 * const dragDrop = new DragDrop({
 *   dragSelector: ".item",
 *   dropSelector: ".items",
 *   permissions: { dragstart: this._canDragStart.bind(this), drop: this._canDragDrop.bind(this) },
 *   callbacks: { dragstart: this._onDragStart.bind(this), drop: this._onDragDrop.bind(this) }
 * });
 * dragDrop.bind(html);
 * ```
 */
class DragDrop {
  /**
   * @param {DragDropConfiguration} [config]
   */
  constructor({dragSelector=null, dropSelector=null, permissions={}, callbacks={}}={}) {
    this.dragSelector = dragSelector;
    this.dropSelector = dropSelector;
    this.permissions = permissions;
    this.callbacks = callbacks;
  }

  /* -------------------------------------------- */
  /*  Properties                                  */
  /* -------------------------------------------- */

  /**
   * A set of callback functions for each action of the drag & drop workflow.
   * @type {Record<"dragstart"|"dragover"|"drop"|"dragenter"|"dragleave"|"dragend", (event: DragEvent) => void>}
   */
  callbacks;

  /**
   * The HTML selector which identifies draggable elements.
   * @type {string|null}
   */
  dragSelector;

  /**
   * The HTML selector which identifies drop targets.
   * @type {string|null}
   */
  dropSelector;

  /**
   * A set of functions to control authorization to begin drag workflows, and drop content.
   * @type {Record<"dragstart"|"drop", (selector: string) => boolean>}
   */
  permissions;

  /* -------------------------------------------- */
  /*  Public API                                  */
  /* -------------------------------------------- */

  /**
   * Bind the DragDrop controller to an HTML application
   * @param {HTMLElement} html    The HTML element to which the handler is bound
   */
  bind(html) {

    // Identify and activate draggable targets
    const canDrag = !!this.dragSelector && this.can("dragstart", this.dragSelector);
    const draggables = this.dragSelector ? html.querySelectorAll(this.dragSelector) : [];
    for ( const element of draggables ) {
      element.setAttribute("draggable", canDrag);
      element.ondragstart = canDrag ? this._handleDragStart.bind(this) : null;
      element.ondragend = canDrag ? this._handleDragEnd.bind(this) : null;
    }

    // Identify and activate drop targets
    const canDrop = this.can("drop", this.dropSelector);
    const droppables = !this.dropSelector || html.matches(this.dropSelector) ? [html]
      : html.querySelectorAll(this.dropSelector);
    for ( const element of droppables ) {
      element.ondragover = canDrop ? this._handleDragOver.bind(this) : null;
      element.ondrop = canDrop ? this._handleDrop.bind(this) : null;
      element.ondragenter = canDrop ? this._handleDragEnter.bind(this) : null;
      element.ondragleave = canDrop ? this._handleDragLeave.bind(this) : null;
    }
    return this;
  }

  /* -------------------------------------------- */

  /**
   * Execute a callback function associated with a certain action in the workflow
   * @param {DragEvent} event   The drag event being handled
   * @param {string} action     The action being attempted
   */
  callback(event, action) {
    const fn = this.callbacks[action];
    if ( fn instanceof Function ) return fn(event);
  }

  /* -------------------------------------------- */

  /**
   * Test whether the current user has permission to perform a step of the workflow
   * @param {string} action     The action being attempted
   * @param {string} selector   The selector being targeted
   * @returns {boolean}          Can the action be performed?
   */
  can(action, selector) {
    const fn = this.permissions[action];
    if ( fn instanceof Function ) return fn(selector);
    return true;
  }

  /* -------------------------------------------- */
  /*  Event Listeners and Handlers                */
  /* -------------------------------------------- */

  /**
   * Handle the start of a drag workflow
   * @param {DragEvent} event   The drag event being handled
   * @protected
   */
  _handleDragStart(event) {
    this.callback(event, "dragstart");
    if ( event.dataTransfer.items.length ) event.stopPropagation();
  }

  /* -------------------------------------------- */

  /**
   * Handle a drag workflow ending for any reason.
   * @param {DragEvent} event  The drag event.
   * @protected
   */
  _handleDragEnd(event) {
    this.callback(event, "dragend");
  }

  /* -------------------------------------------- */

  /**
   * Handle entering a drop target while dragging.
   * @param {DragEvent} event  The drag event.
   * @protected
   */
  _handleDragEnter(event) {
    this.callback(event, "dragenter");
  }

  /* -------------------------------------------- */

  /**
   * Handle leaving a drop target while dragging.
   * @param {DragEvent} event  The drag event.
   * @protected
   */
  _handleDragLeave(event) {
    this.callback(event, "dragleave");
  }

  /* -------------------------------------------- */

  /**
   * Handle a dragged element over a droppable target
   * @param {DragEvent} event   The drag event being handled
   * @protected
   */
  _handleDragOver(event) {
    event.preventDefault();
    this.callback(event, "dragover");
    return false;
  }

  /* -------------------------------------------- */

  /**
   * Handle a dragged element dropped on a droppable target
   * @param {DragEvent} event   The drag event being handled
   * @protected
   */
  _handleDrop(event) {
    event.preventDefault();
    return this.callback(event, "drop");
  }

  /* -------------------------------------------- */
  /*  Helpers                                     */
  /* -------------------------------------------- */

  /**
   * A helper to create an image preview element for use during HTML element dragging.
   * @param {HTMLImageElement} img
   * @param {number} width
   * @param {number} height
   * @returns {HTMLDivElement}
   */
  static createDragImage(img, width, height) {
    let div = document.getElementById("drag-preview");

    // Create the drag preview div
    if ( !div ) {
      div = document.createElement("div");
      div.setAttribute("id", "drag-preview");
      const i = document.createElement("img");
      i.classList.add("noborder");
      div.appendChild(i);
      document.body.appendChild(div);
    }

    // Add the preview image
    const i = div.children[0];
    i.src = img.src;
    i.width = width;
    i.height = height;
    return div;
  }

  /* -------------------------------------------- */
  /*  Factory Methods                             */
  /* -------------------------------------------- */

  /**
   * Retrieve the configured DragDrop implementation.
   * @type {typeof DragDrop}
   */
  static get implementation() {
    let Class = CONFIG.ux.DragDrop;
    if ( !foundry.utils.isSubclass(Class, DragDrop) ) {
      console.warn("Configured DragDrop override must be a subclass of DragDrop.");
      Class = DragDrop;
    }
    return Class;
  }
}

