/**
 * Display the End User License Agreement and prompt the user to agree before moving forwards.
 * @extends ApplicationV2
 * @mixes HandlebarsApplication
 */
class EULA extends HandlebarsApplicationMixin(ApplicationV2) {

  /** @inheritDoc */
  static DEFAULT_OPTIONS = {
    id: "eula",
    classes: ["themed", "theme-dark"],
    tag: "aside",
    window: {
      title: "End User License Agreement",
      icon: "fa-solid fa-file-contract",
      minimizable: false
    },
    position: {
      width: 800,
      height: "auto"
    },
    actions: {
      accept: EULA.#onClickAccept,
      decline: EULA.#onClickDecline
    }
  };

  /** @override */
  static PARTS = {
    content: {
      id: "content",
      template: "templates/setup/parts/eula-content.hbs",
      scrollable: [""]
    },
    form: {
      id: "form",
      template: "templates/setup/parts/eula-form.hbs"
    }
  };

  /* -------------------------------------------- */

  /** @override */
  async _prepareContext(options) {
    const html = await foundry.utils.fetchWithTimeout("license.html").then(r => r.text());
    return {html};
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  async _renderFrame(options) {
    const frame = await super._renderFrame(options);
    this.window.controlsDropdown.remove();
    this.window.close.remove();
    return frame;
  }

  /* -------------------------------------------- */
  /*  Event Listeners and Handlers                */
  /* -------------------------------------------- */

  /**
   * Require the user to have checked the agreement box in order to proceed.
   * @this {EULA}
   * @param {PointerEvent} event
   * @param {HTMLButtonElement} target
   */
  static #onClickAccept(event, target) {
    if ( !this.parts.form.agree.checked ) {
      event.preventDefault();
      event.stopPropagation();
      ui.notifications.error("EULA.ErrorAgreeRequired", {localize: true});
    }
  }

  /* -------------------------------------------- */

  /**
   * Require the user to have checked the agreement box in order to proceed.
   * @this {EULA}
   * @param {PointerEvent} event
   * @param {HTMLButtonElement} target
   */
  static #onClickDecline(event, target) {
    this.parts.form.agree.checked = false;
    ui.notifications.warn("EULA.Declined", {localize: true});
    setTimeout(() => window.location.href = CONST.WEBSITE_URL, 1000);
  }
}

/**
 * The Join Game setup application.
 * @extends ApplicationV2
 * @mixes HandlebarsApplication
 */
class JoinGameForm extends HandlebarsApplicationMixin(ApplicationV2) {
  constructor(options) {
    super(options);
    game.users.apps.push(this);
  }

  /** @inheritDoc */
  static DEFAULT_OPTIONS = {
    id: "join-game",
    window: {
      frame: false,
      positioned: false
    }
  };

  /** @override */
  static PARTS = {
    form: {
      id: "form",
      template: "templates/setup/parts/join-form.hbs",
      forms: {
        "#join-game-form": {
          handler: JoinGameForm.#onSubmitLoginForm
        }
      }
    },
    details: {
      id: "details",
      template: "templates/setup/parts/join-details.hbs"
    },
    setup: {
      id: "setup",
      template: "templates/setup/parts/join-setup.hbs",
      forms: {
        "#join-game-setup": {
          handler: JoinGameForm.#onSubmitSetupForm
        }
      }
    },
    world: {
      id: "world",
      template: "templates/setup/parts/join-world.hbs",
      scrollable: ["#world-description"]
    }
  };

  /* -------------------------------------------- */

  /** @inheritDoc */
  _configureRenderOptions(options) {
    super._configureRenderOptions(options);
    if ( game.world.joinTheme === "minimal" ) {
      const minimalParts = ["form", "setup"];
      options.parts = options.parts.filter(p => minimalParts.includes(p));
    }
  }

  /* -------------------------------------------- */

  /** @override */
  async _prepareContext(options) {
    const context = {
      isAdmin: game.data.isAdmin,
      users: game.users,
      world: game.world,
      passwordString: game.data.passwordString,
      usersCurrent: game.users.filter(u => u.active).length,
      usersMax: game.users.contents.length
    };

    // Next session time
    const nextDate = new Date(game.world.nextSession || undefined);
    if ( nextDate.isValid() ) {
      context.nextTime = nextDate.toLocaleTimeString(game.i18n.lang, {
        weekday: "long",
        month: "short",
        day: "numeric",
        hour: "numeric",
        minute: "numeric",
        timeZoneName: "short"
      });
    }
    return context;
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  _syncPartState(partId, newElement, priorElement, state) {
    super._syncPartState(partId, newElement, priorElement, state);
    // Retain login form state
    if ( partId === "form" ) {
      newElement.userid.value = priorElement.userid.value;
      if ( newElement.userid.selectedOptions[0]?.disabled ) newElement.userid.value = "";
      newElement.password.value = priorElement.password.value;
    }
  }

  /* -------------------------------------------- */
  /*  Event Listeners and Handlers                */
  /* -------------------------------------------- */

  /**
   * @this {JoinGameForm}
   * @param {SubmitEvent} event
   * @param {HTMLFormElement} form
   * @param {foundry.applications.ux.FormDataExtended} formData
   */
  static async #onSubmitSetupForm(event, form, formData) {
    event.preventDefault();
    form.disabled = true;

    // Display a warning if other players are connected
    const othersActive = game.users.filter(u => u.active).length;
    if ( othersActive ) {
      const warning = othersActive > 1 ? "GAME.ReturnSetupActiveUsers" : "GAME.ReturnSetupActiveUser";
      const confirm = await foundry.applications.api.DialogV2.confirm({
        window: {title: "GAME.ReturnSetup"},
        content: `<p>${game.i18n.format(warning, {number: othersActive})}</p>`
      });
      if ( !confirm ) {
        form.disabled = false;
        return;
      }
    }

    // Submit the request
    const postData = Object.assign(formData.object, {action: "shutdown"});
    return this.#post(form, postData);
  }


  /* -------------------------------------------- */

  /**
   * @this {JoinGameForm}
   * @param {SubmitEvent} event
   * @param {HTMLFormElement} form
   * @param {foundry.applications.ux.FormDataExtended} formData
   */
  static async #onSubmitLoginForm(event, form, formData) {
    event.preventDefault();
    if ( !formData.get("userid") ) return ui.notifications.error("JOIN.ErrorMustSelectUser", {localize: true});
    const postData = Object.assign(formData.object, {action: "join"});
    return this.#post(form, postData);
  }

  /* -------------------------------------------- */

  /**
   * Submit join view POST requests to the server for handling.
   * @param {HTMLFormElement} form                    The form being submitted
   * @param {object} postData                         The processed form data
   * @returns {Promise<void>}
   */
  async #post(form, postData) {
    form.disabled = true;
    const joinURL = foundry.utils.getRoute("join");
    const user = game.users.get(postData.userid)?.name || postData.userid;
    let response;

    // Submit the request
    try {
      response = await foundry.utils.fetchJsonWithTimeout(joinURL, {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify(postData)
      });
    }
    catch(e) {
      if (e instanceof foundry.utils.HttpError) {
        ui.notifications.error(e.displayMessage, {format: {user}});
      }
      else {
        ui.notifications.error(foundry.utils.escapeHTML(e));
      }
      form.disabled = false;
      return;
    }

    // Redirect on success
    ui.notifications.info(response.message, {format: {user}});
    setTimeout(() => window.location.href = response.redirect, 500 );
  }
}

/**
 * @import {ServerSettings} from "@common/config.mjs";
 */

/**
 * A form application for managing core server configuration options.
 * @see {@link foundry.config.ServerSettings}
 */
class ServerSettingsConfig extends new HandlebarsApplicationMixin(ApplicationV2) {

  /** @inheritDoc */
  static DEFAULT_OPTIONS = {
    tag: "form",
    id: "server-settings-config",
    window: {
      title: "SERVER_SETTINGS.Title",
      icon: "fa-solid fa-gears",
      contentClasses: ["standard-form"]
    },
    position: {
      width: 720
    },
    actions: {
      changePassword: ServerSettingsConfig.#onChangePassword
    },
    form: {
      handler: ServerSettingsConfig.#onSubmit
    }
  };

  /** @override */
  static PARTS = {
    config: {
      template: "templates/setup/server-settings-config.hbs",
      scrollable: [""]
    },
    footer: {template: "templates/generic/form-footer.hbs"}
  };

  /* -------------------------------------------- */

  /**
   * Which CSS theme is currently being previewed
   * @type {string}
   */
  #previewTheme = game.serverSettings.cssTheme;

  /**
   * Has the ApplicationConfiguration model been localized?
   * @type {boolean}
   */
  #modelLocalized = false;


  /**
   * An ApplicationConfiguration instance which is used for validation and processing of form changes.
   * @type {ServerSettings}
   */
  get settings() {
    return game.serverSettings;
  }

  /* -------------------------------------------- */

  /**
   * Prompt the user with a request to share telemetry data if they have not yet chosen an option.
   */
  static async telemetryRequestDialog() {
    if ( typeof game.data.options.telemetry === "boolean" ) return;
    const content = [`<p>${game.i18n.localize("SERVER_SETTINGS.Telemetry.request1")}</p>`,
      `<blockquote>${game.i18n.localize("SERVER_SETTINGS.FIELDS.telemetry.hint")}</blockquote>`,
      `<p>${game.i18n.localize("SERVER_SETTINGS.Telemetry.request2")}</p>`].join("\n");
    const confirmed = await foundry.applications.api.DialogV2.confirm({
      window: {title: "SERVER_SETTINGS.FIELDS.telemetry.label"},
      position: {width: 480},
      content,
      yes: {label: "SERVER_SETTINGS.Telemetry.yes"},
      no: {label: "SERVER_SETTINGS.Telemetry.no"}
    });
    if ( typeof confirmed == "boolean" ) {
      const {changes} = await game.post({action: "adminConfigure", config: {telemetry: confirmed}});
      foundry.utils.mergeObject(game.data.options, changes);
    }
  }

  /* -------------------------------------------- */

  /** @override */
  _prepareContext(options) {
    const cssThemes = Object.entries(CONST.CSS_THEMES).reduce((themes, [key, label]) => {
      themes[key] = game.i18n.localize(label);
      return themes;
    }, {});
    const languages = game.data.languages.flatMap(l => l.modules.map(m =>
      ({group: l.label, value: `${l.id}.${m.id}`, label: `${l.label} - ${m.label}`})));
    const worlds = game.worlds.contents
      .sort((a, b) => a.title.localeCompare(b.title, game.i18n.lang))
      .reduce((obj, world) => {
        obj[world.id] = world.title;
        return obj;
      }, {});
    const settings = game.serverSettings;
    return {
      rootId: this.id,
      source: settings._source,
      fields: settings.schema.fields,
      cssThemes, languages, worlds,
      noAdminPW: !game.data.options.adminPassword,
      buttons: [{type: "submit", icon: "fa-solid fa-floppy-disk", label: "SERVER_SETTINGS.Save.label"}]
    };
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  async _preFirstRender(context, options) {
    await super._preFirstRender(context, options);
    if ( !this.#modelLocalized ) {
      Localization.localizeDataModel(foundry.config.ServerSettings);
      this.#modelLocalized = true;
    }
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  _onChangeForm(formConfig, event) {
    super._onChangeForm(formConfig, event);
    if ( event.target.name === "cssTheme") this.#applyThemeChange(this.form.cssTheme.value);
  }

  /* -------------------------------------------- */

  /**
   * Handle a request to change the administrator password.
   * @this {ServerSettingsConfig}
   * @returns {Promise<void>}
   */
  static async #onChangePassword() {
    return foundry.applications.api.DialogV2.prompt({
      content: `
        <p>${game.i18n.localize("SERVER_SETTINGS.ChangePassword.hint")}</p>
        <input type="password" name="adminPassword">
      `,
      window: {
        icon: "fa-solid fa-lock",
        title: "SERVER_SETTINGS.ChangePassword.title"
      },
      ok: {
        label: "SERVER_SETTINGS.ChangePassword.label",
        callback: (event, button) => button.form.elements.adminPassword.value
      },
      submit: async (attempt, dialog) => {
        dialog.element.querySelector("button").innerHTML = '<i class="fa-solid fa-spinner fa-spin-pulse" inert></i>';
        const response = await game.post({ action: "adminPassword", adminPassword: attempt });
        if ( response?.result ) {
          const password = document.createElement("input");
          Object.assign(password, { type: "password", name: "adminPassword", value: attempt });
          document.getElementById("changePassword").replaceWith(password);
        }
      }
    });
  }

  /* -------------------------------------------- */

  /** @inheritDoc */
  _onClose(options) {
    super._onClose(options);
    this.#applyThemeChange(this.settings.cssTheme);
  }

  /* -------------------------------------------- */

  /**
   * Handle form submission.
   * @this {ServerSettingsConfig}
   * @type {ApplicationFormSubmission}
   */
  static async #onSubmit(event, form, formData) {
    const original = this.settings.toObject();

    // Validate the proposed changes
    let changes;
    try {
      changes = this.settings.updateSource(formData.object);
    } catch(err) {
      return ui.notifications.error(foundry.utils.escapeHTML(err.message));
    }
    if ( !Object.keys(changes).length ) return this.close();

    // Confirm that a server restart is okay
    const confirmed = await foundry.applications.api.DialogV2.confirm({
      window: {title: "SERVER_SETTINGS.Save.label"},
      position: {width: 480},
      content: `<p>${game.i18n.localize("SERVER_SETTINGS.Save.warning")}</p>`
    });

    // Submit the form
    if ( confirmed ) {
      const response = await game.post({action: "adminConfigure", config: changes});
      if ( response.restart ) ui.notifications.info("SERVER_SETTINGS.Save.restart", {localize: true, permanent: true});
      return this.close();
    }

    // Reset the form
    this.settings.updateSource(original);
  }

  /* -------------------------------------------- */

  /**
   * Update the body class with the previewed CSS theme.
   * @param {string} themeId     The theme ID to preview
   */
  #applyThemeChange(themeId) {
    document.body.classList.replace(`theme-${this.#previewTheme}`, `theme-${themeId}`);
    this.#previewTheme = themeId;
  }
}

