    const button = notes.element.querySelector("button[data-action=update]");
    if ( !button ) return;
    const icon = button.querySelector("i");
    icon.className = progressData.pct < 100 ? "fa-solid fa-spinner fa-pulse" : "fa-solid fa-check";
